import sys
import lzma

def F():
    return [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "dict_size": 1 << 22, "lc": 4, "lp": 0, "pb": 0}]

def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("c", "d"):
        sys.stderr.write("usage: squeeze.py c|d\n")
        sys.exit(2)
    data = sys.stdin.buffer.read()
    if sys.argv[1] == "c":
        out = lzma.compress(data, format=lzma.FORMAT_RAW, filters=F())
    else:
        out = lzma.decompress(data, format=lzma.FORMAT_RAW, filters=F())
    sys.stdout.buffer.write(out)

if __name__ == "__main__":
    main()

